import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Runtime API Index - 运行时 API 索引","description":"","frontmatter":{},"headers":[],"relativePath":"runtimeApiIndex.md","filePath":"runtimeApiIndex.md","lastUpdated":1780847608000}'),a={name:"runtimeApiIndex.md"};function r(i,t,n,s,u,m){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="runtime-api-index-运行时-api-索引" tabindex="-1">Runtime API Index - 运行时 API 索引</h1><p>本章节面向后续知识库构建, 记录 AutoJs6 <code>6.7.0</code> 运行时实际注入到脚本环境的对象、别名、源码路径和文档入口.</p><p>源码基准:</p><ul><li>上游仓库: <code>SuperMonster003/AutoJs6</code></li><li>基准提交: <code>ed3eb10e88db5a8425fd94bdddefa4176e5e1c94</code></li><li>版本: <code>6.7.0</code></li></ul><p>源码依据:</p><ul><li><code>app/src/main/java/org/autojs/autojs/runtime/ScriptRuntime.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/runtime/api/augment/Augmentable.kt</code></li></ul><p>机器可读数据:</p><ul><li><code>json/runtimeApiIndexData.json</code></li></ul><hr><h2 id="注入规则" tabindex="-1">注入规则</h2><p><code>ScriptRuntime.augment(target)</code> 是运行时 API 注入入口. <code>Augmentable.augment(..., withDollarPrefix = true)</code> 会同时注入 <code>name</code> 和 <code>$name</code>; <code>withDollarPrefix = false</code> 只注入原始名称. 部分对象还会通过 <code>assignWithRuntime(...)</code> 直接把函数、类或 getter 写入全局对象.</p><p>因此, 判断某个 API 是否真实存在时, 应优先对照本页和 <code>ScriptRuntime.kt</code>, 其次再看具体模块页面.</p><h2 id="运行时注入对象" tabindex="-1">运行时注入对象</h2><table tabindex="0"><thead><tr><th>注入对象</th><th><code>$</code> 别名</th><th>嵌套 / 全局补充</th><th>主要源码</th><th>文档入口</th></tr></thead><tbody><tr><td><code>global</code> 函数与类</td><td>不适用</td><td><code>Global</code>, <code>GlobalLegacy</code>, <code>GlobalClasses</code> 直接写入全局作用域</td><td><code>augment/global/Global.kt</code><br><code>augment/global/Legacy.kt</code><br><code>augment/global/Classes.kt</code></td><td><a href="./global">Global</a></td></tr><tr><td><code>isNullish</code> / <code>isNonNullish</code></td><td>不适用</td><td>直接写入全局作用域</td><td><code>augment/global/IsNullish.kt</code></td><td><a href="./global">Global</a></td></tr><tr><td><code>util</code></td><td><code>$util</code></td><td><code>java</code>, <code>version</code>, <code>versionCodes</code>, <code>inspect</code>, <code>morseCode</code></td><td><code>augment/util/Util.kt</code><br><code>augment/util/Java.kt</code><br><code>augment/util/Version.kt</code><br><code>augment/util/VersionCodes.kt</code><br><code>augment/util/Inspect.kt</code><br><code>augment/util/MorseCode.kt</code></td><td><a href="./util">Util</a></td></tr><tr><td><code>species</code></td><td><code>$species</code></td><td>判断 JavaScript / Java / Android 对象类型</td><td><code>augment/global/Species.kt</code></td><td><a href="./global">Global</a></td></tr><tr><td><code>app</code></td><td><code>$app</code></td><td><code>app.autojs</code> 指向 <code>autojs</code> 对象</td><td><code>augment/app/App.kt</code></td><td><a href="./app">App</a></td></tr><tr><td><code>autojs</code></td><td><code>$autojs</code></td><td><code>version</code> 子对象</td><td><code>augment/autojs/Autojs.kt</code><br><code>augment/autojs/Version.kt</code></td><td><a href="./autojs">AutoJs6</a></td></tr><tr><td><code>shell</code></td><td><code>$shell</code></td><td>全局 <code>shell(...)</code> 入口与 root shell 辅助</td><td><code>augment/shell/Shell.kt</code></td><td><a href="./shell">Shell</a></td></tr><tr><td><code>timers</code></td><td><code>$timers</code></td><td><code>setTimeout</code>, <code>setInterval</code> 等计时器兼容入口</td><td><code>augment/timers/Timers.kt</code><br><code>augment/timers/SetIntervalExt.kt</code></td><td><a href="./timers">Timer</a></td></tr><tr><td><code>auto</code></td><td><code>$auto</code></td><td>无障碍服务启停、等待、状态</td><td><code>augment/automator/Auto.kt</code></td><td><a href="./automator">Automator</a></td></tr><tr><td><code>automator</code></td><td><code>$automator</code></td><td><code>click</code>, <code>swipe</code>, <code>back</code>, <code>home</code> 等动作还会以全局函数注入</td><td><code>augment/automator/Automator.kt</code></td><td><a href="./automator">Automator</a></td></tr><tr><td><code>selector</code></td><td><code>$selector</code></td><td><code>text</code>, <code>id</code>, <code>className</code> 等选择器构造函数以全局函数注入</td><td><code>augment/selector/Selector.kt</code></td><td><a href="./uiSelectorType">UiSelector</a></td></tr><tr><td><code>events</code></td><td><code>$events</code></td><td>按键、触摸、通知、Toast、无障碍手势事件</td><td><code>augment/events/Events.kt</code><br><code>runtime/api/Events.java</code></td><td><a href="./events">Event</a></td></tr><tr><td><code>keys</code></td><td><code>$keys</code></td><td>按键码和按键辅助函数</td><td><code>augment/events/Keys.kt</code></td><td><a href="./keys">Keys</a></td></tr><tr><td><code>Canvas</code></td><td>否</td><td>可构造类, Canvas / Paint / Path 相关包装</td><td><code>augment/canvas/Canvas.kt</code></td><td><a href="./canvas">Canvas</a></td></tr><tr><td><code>images</code></td><td><code>$images</code></td><td><code>captureScreen</code>, <code>requestScreenCapture</code>, <code>findImage</code> 等部分函数也有全局入口</td><td><code>augment/images/Images.kt</code></td><td><a href="./image">Image</a></td></tr><tr><td><code>ocr</code></td><td><code>$ocr</code></td><td><code>mlkit</code>, <code>paddle</code>, <code>rapid</code> 三个子对象</td><td><code>augment/ocr/Ocr.kt</code><br><code>augment/ocr/OcrMLKit.kt</code><br><code>augment/ocr/OcrPaddle.kt</code><br><code>augment/ocr/OcrRapid.kt</code></td><td><a href="./ocr">OCR</a></td></tr><tr><td><code>barcode</code></td><td><code>$barcode</code></td><td>MLKit 条码识别</td><td><code>augment/barcode/Barcode.kt</code></td><td><a href="./barcode">Barcode</a></td></tr><tr><td><code>qrcode</code></td><td><code>$qrcode</code></td><td>条码识别的二维码限定包装</td><td><code>augment/barcode/QrCode.kt</code></td><td><a href="./qrcode">QR Code</a></td></tr><tr><td><code>threads</code></td><td><code>$threads</code></td><td>线程、锁、原子变量、一次性结果</td><td><code>augment/threads/Threads.kt</code></td><td><a href="./threads">Thread</a></td></tr><tr><td><code>ui</code></td><td><code>$ui</code></td><td>UI DSL、线程调度、控件注册</td><td><code>augment/ui/UI.kt</code><br><code>augment/ui/UIWidget.kt</code></td><td><a href="./ui">UI</a></td></tr><tr><td><code>colors</code></td><td><code>$colors</code></td><td>Android / CSS / Web / Material 色表</td><td><code>augment/colors/Colors.kt</code></td><td><a href="./color">Color</a></td></tr><tr><td><code>color</code></td><td>否</td><td><code>Color</code> 构造与颜色对象能力</td><td><code>augment/colors/Color.kt</code><br><code>augment/colors/ColorNativeObject.kt</code></td><td><a href="./color">Color</a></td></tr><tr><td><code>tasks</code></td><td><code>$tasks</code></td><td>定时任务、广播任务、任务查询与更新</td><td><code>augment/tasks/Tasks.kt</code></td><td><a href="./tasks">Task</a></td></tr><tr><td><code>dialogs</code></td><td><code>$dialogs</code></td><td>对话框构建与显示</td><td><code>augment/dialogs/Dialogs.kt</code></td><td><a href="./dialogs">Dialog</a></td></tr><tr><td><code>continuation</code></td><td><code>$continuation</code></td><td>协程 / continuation 内部模块</td><td><code>augment/continuation/Continuation.kt</code><br><code>augment/continuation/Creator.kt</code></td><td><a href="./continuation">Continuation</a></td></tr><tr><td><code>http</code></td><td><code>$http</code></td><td>OkHttp 请求、响应包装、流式保存</td><td><code>augment/http/Http.kt</code><br><code>augment/http/RequestBuilder.kt</code><br><code>augment/http/ResponseWrapper.kt</code><br><code>augment/http/ResponseBodyNativeObject.kt</code></td><td><a href="./http">HTTP</a></td></tr><tr><td><code>web</code></td><td><code>$web</code></td><td>WebView 注入、WebClient、WebSocket 辅助</td><td><code>augment/web/Web.kt</code></td><td><a href="./web">Web</a></td></tr><tr><td><code>WebSocket</code></td><td>否</td><td>可构造类, 不注入 <code>$WebSocket</code></td><td><code>augment/web/WebSocket.kt</code><br><code>augment/web/WebSocketFields.kt</code></td><td><a href="./webSocketType">WebSocket</a></td></tr><tr><td><code>s13n</code></td><td><code>$s13n</code></td><td>标准化工具</td><td><code>augment/s13n/S13n.kt</code></td><td><a href="./s13n">Standardization</a></td></tr><tr><td><code>cvt</code></td><td><code>$cvt</code></td><td><code>bytes</code> 子对象</td><td><code>augment/converter/Converter.kt</code><br><code>augment/converter/Bytes.kt</code></td><td><a href="./cvt">Cvt</a></td></tr><tr><td><code>fmt</code></td><td><code>$fmt</code></td><td><code>bytes</code> 子对象</td><td><code>augment/formatter/Formatter.kt</code><br><code>augment/formatter/Bytes.kt</code></td><td><a href="./fmt">Fmt</a></td></tr><tr><td><code>console</code></td><td><code>$console</code></td><td>代理全局控制台对象, 含悬浮控制台配置</td><td><code>augment/console/Console.kt</code></td><td><a href="./console">Console</a></td></tr><tr><td><code>plugins</code></td><td><code>$plugins</code></td><td>插件加载与插件上下文</td><td><code>augment/plugins/Plugins.kt</code></td><td><a href="./plugins">Plugins</a></td></tr><tr><td><code>Arrayx</code></td><td>否</td><td><code>Array</code> 扩展工具对象</td><td><code>augment/jsox/Arrayx.kt</code></td><td><a href="./arrayx">Arrayx</a></td></tr><tr><td><code>Numberx</code></td><td>否</td><td><code>Number</code> 扩展工具对象</td><td><code>augment/jsox/Numberx.kt</code></td><td><a href="./numberx">Numberx</a></td></tr><tr><td><code>Mathx</code></td><td>否</td><td><code>Math</code> 扩展工具对象</td><td><code>augment/jsox/Mathx.kt</code></td><td><a href="./mathx">Mathx</a></td></tr><tr><td><code>jsox</code></td><td><code>$jsox</code></td><td>JavaScript 内建对象扩展聚合</td><td><code>augment/jsox/Jsox.kt</code></td><td>暂无独立页; 相关页见 <a href="./polyfill">Polyfill</a>, <a href="./arrayx">Arrayx</a>, <a href="./numberx">Numberx</a>, <a href="./mathx">Mathx</a></td></tr><tr><td><code>files</code></td><td><code>$files</code></td><td>全局 <code>open</code>、路径解析、读写、复制移动</td><td><code>augment/files/Files.kt</code></td><td><a href="./files">File</a></td></tr><tr><td><code>crypto</code></td><td><code>$crypto</code></td><td>加密、摘要、密钥、密钥对</td><td><code>augment/cryptyo/Crypto.kt</code></td><td><a href="./crypto">Crypto</a></td></tr><tr><td><code>RootAutomator</code></td><td>否</td><td>可构造类, 依赖 root 或 Shizuku</td><td><code>augment/automator/RootAutomator.kt</code><br><code>augment/automator/RootAutomatorNativeObject.kt</code></td><td><a href="./automator">Automator</a></td></tr><tr><td><code>engines</code></td><td><code>$engines</code></td><td>脚本执行、执行配置、引擎列表</td><td><code>augment/engines/Engines.kt</code></td><td><a href="./engines">Engine</a></td></tr><tr><td><code>floaty</code></td><td><code>$floaty</code></td><td>悬浮窗、悬浮窗权限、Android Q+ 剪贴板辅助</td><td><code>augment/floaty/Floaty.kt</code><br><code>runtime/api/Floaty.kt</code></td><td><a href="./floaty">Floaty</a></td></tr><tr><td><code>storages</code></td><td><code>$storages</code></td><td>本地键值存储</td><td><code>augment/storages/Storages.kt</code><br><code>augment/storages/StorageNativeObject.kt</code></td><td><a href="./storages">Storage</a></td></tr><tr><td><code>device</code></td><td><code>$device</code></td><td>设备信息、亮度、音量、电量、屏幕、指针位置</td><td><code>augment/device/Device.kt</code><br><code>runtime/api/Device.java</code></td><td><a href="./device">Device</a></td></tr><tr><td><code>recorder</code></td><td><code>$recorder</code></td><td>录制与输入事件相关能力</td><td><code>augment/recorder/Recorder.kt</code></td><td><a href="./recorder">Recorder</a></td></tr><tr><td><code>toast</code></td><td><code>$toast</code></td><td>Toast 显示与解析</td><td><code>augment/toast/Toast.kt</code><br><code>augment/toast/ToastParser.kt</code></td><td><a href="./toast">Toast</a></td></tr><tr><td><code>media</code></td><td><code>$media</code></td><td>媒体库扫描等 Android media 能力</td><td><code>augment/media/Media.kt</code></td><td><a href="./media">Media</a></td></tr><tr><td><code>sensors</code></td><td><code>$sensors</code></td><td>传感器注册与事件</td><td><code>augment/sensors/Sensors.kt</code></td><td><a href="./sensors">Sensor</a></td></tr><tr><td><code>base64</code></td><td><code>$base64</code></td><td>Base64 编解码</td><td><code>augment/base64/Base64.kt</code></td><td><a href="./base64">Base64</a></td></tr><tr><td><code>notice</code></td><td><code>$notice</code></td><td><code>channel</code> 子对象, 通知发布与渠道管理</td><td><code>augment/notice/Notice.kt</code><br><code>augment/notice/Channel.kt</code></td><td><a href="./notice">Notice</a></td></tr><tr><td><code>shizuku</code></td><td><code>$shizuku</code></td><td>命令执行、状态、前台组件查询</td><td><code>augment/shizuku/Shizuku.kt</code></td><td><a href="./shizuku">Shizuku</a></td></tr><tr><td><code>opencc</code></td><td><code>$opencc</code></td><td>中文转换</td><td><code>augment/opencc/OpenCC.kt</code></td><td><a href="./opencc">OpenCC</a></td></tr><tr><td><code>mime</code></td><td><code>$mime</code></td><td>MIME 字符串解析</td><td><code>augment/mime/Mime.kt</code><br><code>augment/mime/JsMime.kt</code></td><td><a href="./mime">MIME</a></td></tr><tr><td><code>sysprops</code></td><td><code>$sysprops</code></td><td>Android 系统属性读取</td><td><code>augment/sysprops/Sysprops.kt</code></td><td><a href="./sysprops">Sysprops</a></td></tr><tr><td><code>sqlite</code></td><td><code>$sqlite</code></td><td>SQLite 打开、<code>Database</code>, <code>CursorWrapper</code></td><td><code>augment/sqlite/SQLite.kt</code><br><code>runtime/api/SQLite.kt</code><br><code>core/database/Database.java</code></td><td><a href="./sqlite">SQLite</a></td></tr><tr><td><code>zip</code></td><td><code>$zip</code></td><td>Zip4j 包装、<code>ZipOptions</code>, <code>ZipNativeObject</code></td><td><code>augment/zip/Zip.kt</code><br><code>augment/zip/ZipNativeObject.kt</code></td><td><a href="./zip">Zip</a></td></tr><tr><td><code>nanoid</code></td><td><code>$nanoid</code></td><td>Nano ID 生成</td><td><code>augment/nanoid/NanoID.kt</code></td><td><a href="./nanoid">NanoID</a></td></tr><tr><td><code>pinyin</code></td><td><code>$pinyin</code></td><td>拼音转换核心</td><td><code>augment/pinyin/Pinyin.kt</code><br><code>augment/pinyin/PinyinCore.kt</code></td><td><a href="./pinyin">Pinyin</a></td></tr><tr><td><code>pinyin4j</code></td><td><code>$pinyin4j</code></td><td>Pinyin4j 兼容入口</td><td><code>augment/pinyin4j/Pinyin4j.kt</code></td><td><a href="./pinyin4j">Pinyin4j</a></td></tr><tr><td><code>mediainfo</code></td><td><code>$mediainfo</code></td><td>MediaInfo 原生库包装</td><td><code>augment/mediainfo/Mediainfo.kt</code><br><code>augment/mediainfo/MediainfoNativeObject.kt</code></td><td><a href="./mediainfo">MediaInfo</a></td></tr></tbody></table><h2 id="高频独立类型页" tabindex="-1">高频独立类型页</h2><p>P2 已将以下高频运行时返回类型或选项对象拆为独立页面, 便于知识库按类型建立节点:</p><ul><li><a href="./zipOptionsType">ZipOptions</a></li><li><a href="./zipNativeObjectType">ZipNativeObject</a></li><li><a href="./databaseType">Database</a></li><li><a href="./cursorWrapperType">CursorWrapper</a></li><li><a href="./httpSaveResultType">HttpSaveResult</a></li><li><a href="./jsMimeType">JsMime</a></li><li><a href="./mediainfoNativeObjectType">MediainfoNativeObject</a></li></ul><h2 id="旧-auto-js-4-x-残留核对" tabindex="-1">旧 Auto.js 4.x 残留核对</h2><p>本轮已对 P0 / P1 / P2 覆盖页面中的旧 Auto.js 4.x 叙述进行集中核对:</p><table tabindex="0"><thead><tr><th>位置</th><th>当前处理</th></tr></thead><tbody><tr><td><a href="./http">HTTP</a>, <a href="./web">Web</a>, <a href="./ocr">OCR</a>, <a href="./console">Console</a></td><td>已按 AutoJs6 <code>6.7.0</code> 源码改写旧行为说明, 废弃 / abandoned API 已标注.</td></tr><tr><td><a href="./uiSelectorType">UiSelector</a></td><td>仍保留 Auto.js 4.x 差异提示, 但已明确为兼容差异说明, 不是当前行为.</td></tr><tr><td><a href="./qa">Q &amp; A</a>, <a href="./documentation">About</a>, <a href="./overview">Overview</a>, <a href="./progress">Progress</a></td><td>保留项目来源和历史背景叙述; 不作为当前 API 行为依据.</td></tr><tr><td><code>timers</code>, <code>shell</code>, <code>ui</code>, <code>modules</code>, <code>threads</code>, <code>image</code>, <code>events</code>, <code>media</code> 等未进入 P0 / P1 的旧章节</td><td>已在 <a href="./documentationRoadmap">Documentation Roadmap</a> 中作为后续源码校对风险保留; 知识库回答当前行为时不应优先引用这些旧章节.</td></tr></tbody></table><p>判断原则: 当历史背景与本页运行时索引、具体页面 &quot;源码依据&quot; 小节或源码路径冲突时, 以后者为准.</p>',21)])])}const h=d(a,[["render",r]]);export{p as __pageData,h as default};
